'use strict';
function services(){state.services??={assignments:{},trees:[],boats:[],sound:false};return state.services}
const serviceDefs=[['szpital','✚','Szpital',70,30,'Medyk leczy swoich żołnierzy w promieniu 6 pól.'],['lesniczowka','♧','Leśniczówka',40,10,'Leśnik sadzi drzewa w promieniu 6 pól.']];
for(const d of serviceDefs){defs.push(d);WORK_TYPES.push(d[0]);const b=document.createElement('button');b.textContent=d[1]+' '+d[2]+' · '+d[3]+' drewna, '+d[4]+' kamienia';b.onclick=()=>setMode(d[0]);$('buildings').append(b)}
function workId(b){return b.x+','+b.y+','+b.type}
function allowedWork(b,id){const a=services().assignments[id];return !a||a===workId(b)}
function reservedWork(b,id){return Object.entries(services().assignments).some(([other,key])=>+other!==id&&key===workId(b)&&residents.some(r=>r.id===+other))}
function assignWork(id,key){const r=residents.find(r=>r.id===id),b=state.buildings.find(b=>workId(b)===key&&WORK_TYPES.includes(b.type));if(!r||key&&(!b||reservedWork(b,id)))return false;if(key)services().assignments[id]=key;else delete services().assignments[id];residentAssignmentTask=null;residentRouteQueue=[];for(const u of residents){u.routePending=false;if(u===r||u.job===b){u.job=null;u.path=[];u.phase='szuka pracy';u.wait=0}}peopleSignature='';syncResidents();save();renderServices();return true}
const servicesSync=syncResidents;syncResidents=function(){const a=services().assignments;for(const [id,key] of Object.entries(a))if(!state.buildings.some(b=>workId(b)===key&&WORK_TYPES.includes(b.type)))delete a[id];for(const r of residents)if(r.job&&(!allowedWork(r.job,r.id)||reservedWork(r.job,r.id))){r.job=null;r.path=[]}servicesSync()};
const servicesNatural=natural;natural=function(x,y){const t=services().trees.find(t=>t.x===x&&t.y===y);if(t&&t.ready&&terrain(x,y)==='grass'&&!building(x,y)&&!cut.has(tileKey(x,y)))return 'tree';return servicesNatural(x,y)};
function plantTree(x,y){if(!state.settled||terrain(x,y)!=='grass'||natural(x,y)||building(x,y)||foreignBuilding(x,y)||services().trees.some(t=>t.x===x&&t.y===y)||x<0||y<0||x>=N||y>=N)return false;services().trees.push({x,y,age:0,ready:false});return true}
function plantNear(b){for(let i=0;i<169;i++){const dx=i%13-6,dy=Math.floor(i/13)-6;if(Math.hypot(dx,dy)>6||Math.abs(dx)+Math.abs(dy)<2)continue;if(plantTree(b.x+dx,b.y+dy))return true}return false}
let bellContext;
function ringBell(){if(!services().sound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;bellContext??=new Audio();bellContext.resume();for(let i=0;i<3;i++){const o=bellContext.createOscillator(),g=bellContext.createGain(),t=bellContext.currentTime+i*.45;o.frequency.value=660;g.gain.setValueAtTime(.12,t);g.gain.exponentialRampToValueAtTime(.001,t+.4);o.connect(g);g.connect(bellContext.destination);o.start(t);o.stop(t+.4)}}catch{}}
const servicesAlarm=setVillageAlarm;setVillageAlarm=function(active){const changed=active!==villageProgress().alarm;servicesAlarm(active);if(active&&changed)ringBell()};
function alarmHint(){if(!villageProgress().alarm)return 'Brak alarmu — mieszkańcy mogą pracować.';if(!lifeState().autoAlarm)return 'Alarm ręczny — zakończ go przyciskiem.';const danger=state.war.raids.some(r=>!r.camp&&r.power>0)||state.towns.some(t=>t.relation==='war'&&t.raidTimer<=45);return danger?'Alarm: zagrożenie trwa.':'Powrót do pracy za '+Math.max(0,Math.ceil(10-lifeState().safeSeconds))+' s gry.'}
function portExit(b){for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]])if(navalWalkable(b.x+dx,b.y+dy))return {x:b.x+dx,y:b.y+dy};return null}
const boatPlans=new Map();
function* boatRoute(a,b){const q=[a],parents=new Map([[tileKey(a.x,a.y),null]]);for(let i=0;i<q.length&&i<30000;i++){const p=q[i];if(p.x===b.x&&p.y===b.y){const out=[];let v=p;while(v){out.push({x:(v.x+.5)*T,y:(v.y+.5)*T});v=parents.get(tileKey(v.x,v.y))}return out.reverse()}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const x=p.x+dx,y=p.y+dy,k=tileKey(x,y);if(!parents.has(k)&&x>=0&&y>=0&&x<N&&y<N&&navalWalkable(x,y)){parents.set(k,p);q.push({x,y})}}if(i%64===63)yield}return null}
function launchCivilBoat(kind,fromKey,toKey){const ports=state.buildings.filter(b=>b.type==='port'),from=ports.find(b=>workId(b)===fromKey),to=ports.find(b=>workId(b)===toKey),a=from&&portExit(from),z=to&&portExit(to);if(!a||services().boats.filter(s=>s.from===fromKey).length>=3||state.wood<30||state.gold<20||!['fish','cargo'].includes(kind))return false;if(kind==='cargo'&&(!z||from===to||state.wood<50))return false;state.wood-=30;state.gold-=20;const s={id:'boat-'+(services().nextBoatId=(services().nextBoatId||0)+1),kind,from:fromKey,to:toKey,x:(a.x+.5)*T,y:(a.y+.5)*T,path:[],wait:kind==='fish'?12:0,cargo:kind==='cargo'?20:0,status:kind==='fish'?'Łowi ryby':'Szuka trasy'};if(s.cargo)state.wood-=20;services().boats.push(s);save();return true}
function updateCivilBoats(dt){for(const s of services().boats){const from=state.buildings.find(b=>workId(b)===s.from&&b.type==='port'),to=state.buildings.find(b=>workId(b)===s.to&&b.type==='port');if(!from||s.kind==='cargo'&&!to){s.status='Port zniszczony — odwołaj łódź';continue}s.wait-=dt;if(s.kind==='fish'){if(!navalWalkable(Math.floor(s.x/T),Math.floor(s.y/T))){s.status='Łowisko zablokowane';continue}s.status='Łowi ryby';if(s.wait<=0){s.wait=12;state.food=Math.min(capacity(),state.food+4)}continue}if(!s.cargo){s.status='Dostarczono 20 drewna · zarobiono 30 monet';continue}if(s.path.length){const p=s.path[0];if(!navalWalkable(Math.floor(p.x/T),Math.floor(p.y/T))){s.path=[];s.wait=3;s.status='Trasa zablokowana';continue}const dx=p.x-s.x,dy=p.y-s.y,d=Math.hypot(dx,dy),step=85*dt;if(d<=step){s.x=p.x;s.y=p.y;s.path.shift();if(!s.path.length){s.cargo=0;state.gold+=30;s.status='Dostarczono';save()}}else{s.x+=dx/d*step;s.y+=dy/d*step}s.status=s.cargo?'Transportuje 20 drewna':'Dostarczono';continue}if(s.wait>0)continue;let task=boatPlans.get(s);if(!task){const z=portExit(to);if(!z){s.wait=3;s.status='Port docelowy zablokowany';continue}task=boatRoute({x:Math.floor(s.x/T),y:Math.floor(s.y/T)},z);boatPlans.set(s,task)}const result=task.next();if(result.done){boatPlans.delete(s);s.path=result.value||[];if(!result.value){s.wait=5;s.status='Brak drogi wodnej'}else s.status='Transportuje 20 drewna'}}}
function cancelCivilBoat(id){const s=services().boats.find(b=>b.id===id);if(!s)return;state.wood+=s.cargo;boatPlans.delete(s);services().boats=services().boats.filter(b=>b!==s);save();renderServices()}
let serviceClock=0;
function updateServices(dt){const s=services();for(let i=s.trees.length-1;i>=0;i--){const t=s.trees[i];if(building(t.x,t.y)||t.ready&&cut.has(tileKey(t.x,t.y))){s.trees.splice(i,1);continue}t.age+=dt;if(!t.ready&&t.age>=60){t.ready=true;cut.delete(tileKey(t.x,t.y))}}for(const r of residents){if(r.phase!=='praca'||!r.job||villageProgress().alarm)continue;if(r.job.type==='szpital')for(const u of ownSoldierActors()){if(u.hp>0&&u.hp<8&&!u.fighting&&Math.hypot(u.x-r.x,u.y-r.y)<=6*T)u.hp=Math.min(8,u.hp+dt*1.5)}if(r.job.type==='lesniczowka'){r.plantClock=(r.plantClock||0)+dt;if(r.plantClock>=12){r.plantClock%=12;plantNear(r.job)}}}updateCivilBoats(dt);serviceClock+=dt;if(serviceClock>=1){serviceClock=0;$('serviceAlarm').textContent=alarmHint()}}
const servicesStep=simulationStep;simulationStep=function(dt){servicesStep(dt);updateServices(dt)};
const servicesStructure=structure;structure=function(b,x,y){if(['szpital','lesniczowka'].includes(b.type)){servicesStructure({...b,type:'dom'},x,y);ctx.fillStyle=b.type==='szpital'?'#c65a4c':'#3b8056';ctx.font='bold 22px system-ui';ctx.fillText(b.type==='szpital'?'✚':'♧',x-10,y-25);return}servicesStructure(b,x,y)};
const servicesWorld=drawWarWorld;drawWarWorld=function(){servicesWorld();for(const t of services().trees)if(!t.ready&&seen.has(tileKey(t.x,t.y))){ctx.fillStyle='#34754b';ctx.fillRect((t.x+.5)*T-2,(t.y+.5)*T-6,4,12);ctx.beginPath();ctx.arc((t.x+.5)*T,(t.y+.5)*T-7,6,0,7);ctx.fill()}for(const s of services().boats)if(seen.has(tileKey(Math.floor(s.x/T),Math.floor(s.y/T)))){ctx.fillStyle='#9b7045';ctx.fillRect(s.x-14,s.y-5,28,10);ctx.fillStyle='#f2d58f';ctx.font='16px system-ui';ctx.fillText(s.kind==='fish'?'♓':'▣',s.x-7,s.y-9)}};
const servicePanel=document.createElement('aside');servicePanel.id='servicesPanel';servicePanel.className='war-panel hidden';servicePanel.innerHTML='<div class="war-title"><h2>Praca, medycy i port</h2><button id="servicesClose">✕</button></div><p id="serviceAlarm"></p><div id="servicesContent"></div>';document.body.append(servicePanel);const serviceOpen=document.createElement('button');serviceOpen.textContent='♧ Praca, medycy i port';serviceOpen.onclick=()=>{$('servicesPanel').classList.remove('hidden');renderServices()};$('clockControls').append(serviceOpen);$('servicesClose').onclick=()=>$('servicesPanel').classList.add('hidden');
function renderServices(){const s=services(),jobs=state.buildings.filter(b=>WORK_TYPES.includes(b.type)),ports=state.buildings.filter(b=>b.type==='port');$('serviceAlarm').textContent=alarmHint();$('servicesContent').innerHTML='<h3>Ręczny przydział pracy</h3><p>Wybierz mieszkańca i stanowisko. Ręczny przydział rezerwuje miejsce; po zamknięciu drogi pracownik zaczeka.</p><select id="workerChoice" aria-label="Mieszkaniec">'+residents.map(r=>'<option value="'+r.id+'" '+(selectedResident===r.id?'selected':'')+'>'+r.name+(s.assignments[r.id]?' · przydział ręczny':'')+' · '+(r.job?defs.find(d=>d[0]===r.job.type)?.[2]:'bez pracy')+'</option>').join('')+'</select><select id="jobChoice" aria-label="Stanowisko"><option value="">Automatyczny wybór pracy</option>'+jobs.map(b=>'<option value="'+workId(b)+'">'+defs.find(d=>d[0]===b.type)?.[2]+' · '+b.x+', '+b.y+'</option>').join('')+'</select><button id="assignJob">Przydziel pracę</button><h3>Szpital i las</h3><p>Zbuduj szpital i leśniczówkę z listy budynków. Medyk leczy żywych żołnierzy poza walką w promieniu 6 pól. Leśnik sadzi drzewo co 12 sekund pracy; rośnie ono przez 60 sekund. Drzewa można ponownie ścinać.</p><button id="plantService">Posadź sadzonkę obok ludka · 2 drewna</button><h3>Dzwon</h3><button id="bellSound">'+(s.sound?'Wycisz dzwon':'Włącz dźwięk dzwonu')+'</button><button id="bellAlarm">'+(villageProgress().alarm?'Zakończ alarm':'Ogłoś alarm')+'</button><p>'+alarmHint()+'</p><h3>Rozbudowa portu</h3><p>Do 3 łodzi cywilnych na port. Łódź kosztuje 30 drewna i 20 monet. Rybacka dostarcza 4 żywności co 12 s. Transportowa przewozi 20 drewna do drugiego własnego portu i zarabia 30 monet po dotarciu. Odwołanie zwraca niedostarczony ładunek.</p><select id="boatFrom" aria-label="Port początkowy">'+ports.map(b=>'<option value="'+workId(b)+'">Port '+b.x+', '+b.y+'</option>').join('')+'</select><select id="boatTo" aria-label="Port docelowy">'+ports.map(b=>'<option value="'+workId(b)+'">Port '+b.x+', '+b.y+'</option>').join('')+'</select><button id="fishBoat">Zbuduj łódź rybacką</button><button id="cargoBoat">Wyślij transport</button>'+s.boats.map(b=>'<p>'+(b.kind==='fish'?'Rybacka':'Transport')+' · '+b.status+' <button data-cancel-boat="'+b.id+'">Odwołaj</button></p>').join('');$('assignJob').onclick=()=>{if(!assignWork(+$('workerChoice').value,$('jobChoice').value))say('Stanowisko zarezerwowane lub niedostępne.')};$('plantService').onclick=()=>{if(state.wood>=2&&plantNear({x:Math.floor(state.p.x/T),y:Math.floor(state.p.y/T)})){state.wood-=2;save();say('Posadzono sadzonkę. Wyrośnie za 60 sekund gry.')}};$('bellSound').onclick=()=>{s.sound=!s.sound;ringBell();save();renderServices()};$('bellAlarm').onclick=()=>{setVillageAlarm(!villageProgress().alarm);renderServices()};for(const [id,kind] of [['fishBoat','fish'],['cargoBoat','cargo']])$(id).onclick=()=>{if(!launchCivilBoat(kind,$('boatFrom').value,$('boatTo').value))say('Sprawdź zasoby, dostęp do wody i limit łodzi. Transport wymaga dwóch różnych portów.');renderServices()}}
$('servicesContent').onclick=e=>{const b=e.target.closest('[data-cancel-boat]');if(b)cancelCivilBoat(b.dataset.cancelBoat)};
const servicesOpenVillage=openVillage;openVillage=function(){servicesOpenVillage();if(selectedResident!==null){$('servicesPanel').classList.remove('hidden');renderServices()}};
window.addEventListener('keydown',e=>{if(e.key==='Escape')$('servicesPanel').classList.add('hidden')});services();

const serviceBadge=document.createElement('span');serviceBadge.id='serviceGlobalAlarm';$('clockControls').append(serviceBadge);const serviceUI=ui;ui=function(){serviceUI();serviceBadge.textContent=villageProgress().alarm?'🔔 '+alarmHint():''};
